CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE anonymous_sessions(id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runtime_config_revisions(id text PRIMARY KEY, profile jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runtime_settings(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), config_id text NOT NULL REFERENCES runtime_config_revisions);
CREATE TABLE credentials(name text PRIMARY KEY, ciphertext bytea NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE video_sources(id text PRIMARY KEY, platform text NOT NULL, canonical_id text NOT NULL, part_key text NOT NULL, canonical_url text NOT NULL, UNIQUE(platform,canonical_id,part_key));
CREATE TABLE source_snapshots(id text PRIMARY KEY, source_id text NOT NULL REFERENCES video_sources, video_hash text NOT NULL, text_hash text NOT NULL, duration_ms bigint NOT NULL CHECK(duration_ms>0), source jsonb NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,video_hash,text_hash));
CREATE TABLE transcript_segments(id text PRIMARY KEY, snapshot_id text NOT NULL REFERENCES source_snapshots, ordinal integer NOT NULL, start_ms bigint NOT NULL CHECK(start_ms>=0), end_ms bigint NOT NULL CHECK(end_ms>start_ms), text text NOT NULL, origin text NOT NULL, UNIQUE(snapshot_id,ordinal));
CREATE INDEX transcript_time ON transcript_segments(snapshot_id,start_ms);
CREATE TABLE job_runs(
 id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('source.prepare','source.restore','article.generate','qa.answer')), work_key text NOT NULL,
 source_id text NOT NULL REFERENCES video_sources, snapshot_id text REFERENCES source_snapshots, config_id text NOT NULL REFERENCES runtime_config_revisions,
 status text NOT NULL CHECK(status IN ('queued','running','retry_wait','waiting_dependency','cancel_requested','succeeded','failed','canceled')), phase text,
 dispatch_generation bigint NOT NULL DEFAULT 1, execution_epoch bigint NOT NULL DEFAULT 0, attempt_no integer NOT NULL DEFAULT 0, failure_count integer NOT NULL DEFAULT 0,
 active_ms bigint NOT NULL DEFAULT 0, deadline_at timestamptz NOT NULL, queued_at timestamptz NOT NULL DEFAULT now(), lease_owner text, lease_expires_at timestamptz,
 last_event_seq bigint NOT NULL DEFAULT 0, had_activity boolean NOT NULL DEFAULT false, checkpoint jsonb NOT NULL DEFAULT '{"schema_version":1}', failure jsonb, result_id text, dependency_run_id text REFERENCES job_runs,
 restore_used boolean NOT NULL DEFAULT false, retry_not_before timestamptz, retry_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX active_work_key ON job_runs(kind,work_key) WHERE status IN ('queued','running','retry_wait','waiting_dependency','cancel_requested');
CREATE INDEX runs_recovery ON job_runs(status,lease_expires_at);
CREATE TABLE job_attempts(id text PRIMARY KEY, run_id text NOT NULL REFERENCES job_runs, attempt_no integer NOT NULL, execution_epoch bigint NOT NULL, dispatch_generation bigint NOT NULL, worker_instance text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), heartbeat_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, outcome text, UNIQUE(run_id,attempt_no), UNIQUE(run_id,execution_epoch));
CREATE TABLE task_outbox(id bigserial PRIMARY KEY, run_id text NOT NULL REFERENCES job_runs, dispatch_generation bigint NOT NULL, queue text NOT NULL, not_before timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, claimed_until timestamptz, failures integer NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,dispatch_generation));
CREATE INDEX outbox_delivery ON task_outbox(not_before) WHERE delivered_at IS NULL;
CREATE TABLE generation_requests(id text PRIMARY KEY, session_id text NOT NULL REFERENCES anonymous_sessions, input_url text NOT NULL, source_id text NOT NULL REFERENCES video_sources, snapshot_id text REFERENCES source_snapshots, active_run_id text REFERENCES job_runs, article_id text, config_id text NOT NULL REFERENCES runtime_config_revisions, revision bigint NOT NULL DEFAULT 1, status text NOT NULL CHECK(status IN ('waiting_source','generating','completed','failed','canceled')), reuse text NOT NULL DEFAULT 'pending', retry_of_id text REFERENCES generation_requests, segments jsonb NOT NULL DEFAULT '[]', failure jsonb, deadline_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX requests_run ON generation_requests(active_run_id,status);
CREATE TABLE idempotency(scope text NOT NULL, key text NOT NULL, hash text NOT NULL, resource_id text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope,key));
CREATE TABLE media_assets(id text PRIMARY KEY, snapshot_id text REFERENCES source_snapshots, source_id text NOT NULL REFERENCES video_sources, run_id text NOT NULL REFERENCES job_runs, kind text NOT NULL CHECK(kind IN ('video','audio','frame')), storage_key text NOT NULL UNIQUE, sha256 text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL CHECK(bytes>=0), state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','deleting','deleted','unavailable')), time_ms bigint, requested_time_ms bigint, width integer NOT NULL DEFAULT 0, height integer NOT NULL DEFAULT 0, caption text NOT NULL DEFAULT '', crop jsonb, replaces_frame_id text REFERENCES media_assets, expires_at timestamptz, delete_failures integer NOT NULL DEFAULT 0, delete_not_before timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assets_expiry ON media_assets(state,expires_at);
CREATE INDEX assets_snapshot ON media_assets(snapshot_id,kind);
CREATE TABLE asset_refs(asset_id text NOT NULL REFERENCES media_assets, owner_type text NOT NULL, owner_id text NOT NULL, expires_at timestamptz, PRIMARY KEY(asset_id,owner_type,owner_id));
CREATE TABLE run_operations(run_id text NOT NULL REFERENCES job_runs, operation_key text NOT NULL, attempt_id text REFERENCES job_attempts, kind text NOT NULL, args_hash text NOT NULL, status text NOT NULL, submissions integer NOT NULL DEFAULT 0, result jsonb, provider_request_id text, usage jsonb, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,operation_key));
CREATE TABLE evidence_questions(id text PRIMARY KEY, run_id text NOT NULL REFERENCES job_runs, snapshot_id text NOT NULL REFERENCES source_snapshots, data jsonb NOT NULL);
CREATE TABLE observations(id text PRIMARY KEY, run_id text NOT NULL REFERENCES job_runs, snapshot_id text NOT NULL REFERENCES source_snapshots, operation_key text NOT NULL, inspection_id text NOT NULL, data jsonb NOT NULL, UNIQUE(run_id,operation_key));
CREATE TABLE articles(id text PRIMARY KEY, generation_run_id text NOT NULL UNIQUE REFERENCES job_runs, snapshot_id text NOT NULL REFERENCES source_snapshots, config_id text NOT NULL REFERENCES runtime_config_revisions, reuse_key text NOT NULL, content jsonb NOT NULL, published_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX article_reuse ON articles(reuse_key);
ALTER TABLE generation_requests ADD CONSTRAINT request_article_fk FOREIGN KEY(article_id) REFERENCES articles;
CREATE TABLE qa_conversations(id text PRIMARY KEY, session_id text NOT NULL REFERENCES anonymous_sessions, request_id text NOT NULL REFERENCES generation_requests, article_id text NOT NULL REFERENCES articles, snapshot_id text NOT NULL REFERENCES source_snapshots, last_turn_id text, active_turn_id text, next_turn_no bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,request_id));
CREATE TABLE qa_turns(id text PRIMARY KEY, conversation_id text NOT NULL REFERENCES qa_conversations, request_id text NOT NULL REFERENCES generation_requests, article_id text NOT NULL REFERENCES articles, snapshot_id text NOT NULL REFERENCES source_snapshots, run_id text NOT NULL UNIQUE REFERENCES job_runs, turn_no bigint NOT NULL, revision bigint NOT NULL DEFAULT 1, status text NOT NULL, question text NOT NULL, context jsonb NOT NULL, retry_of_id text REFERENCES qa_turns, answer jsonb, failure jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, UNIQUE(conversation_id,turn_no));
ALTER TABLE qa_conversations ADD CONSTRAINT last_turn_fk FOREIGN KEY(last_turn_id) REFERENCES qa_turns;
ALTER TABLE qa_conversations ADD CONSTRAINT active_turn_fk FOREIGN KEY(active_turn_id) REFERENCES qa_turns;
CREATE TABLE run_events(run_id text NOT NULL REFERENCES job_runs, seq bigint NOT NULL, event_type text NOT NULL, step_id text, step jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,seq));
CREATE INDEX event_steps ON run_events(run_id,step_id,seq DESC);
CREATE TABLE resource_leases(resource text NOT NULL, slot integer NOT NULL, owner text NOT NULL, run_id text NOT NULL REFERENCES job_runs, execution_epoch bigint NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(resource,slot));
CREATE TABLE storage_reservations(run_id text PRIMARY KEY REFERENCES job_runs, temp_bytes bigint NOT NULL DEFAULT 0, image_bytes bigint NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL);
